E, M, S, H = 'easy', 'medium', 'sufficient', 'hard'

def ckt(rs, mode='series', src='U', amm=True, volt='total'):
    return {"kind": "circuit", "mode": mode, "resistors": rs, "source": src, "ammeter": amm, "voltmeter": volt}

